INSERT INTO feature VALUES('boundary-classification','storage','Alias and boundary classification','value-plane','implemented','notable',NULL,'A value''s constructors are classified as aliases or boundaries on the chunk DAG: the manifest carries the classification into the identity, a boundary exit is a cut candidate, an alias recursing through aliases alone and an alias seam at a chunk boundary are refused by name.','storage-values','crates/storage-values/tests/classification.rs crates/storage-values/tests/manifest.rs',NULL,'#317');
